<?php
session_start(); require 'config/database.php'; require 'lib_results.php';
if(!isset($_SESSION['user'])){header('Location: login.php');exit;}
$role=$_SESSION['user']['role']; $studentId=(int)($_GET['student_id']??0); $term=trim($_GET['term']??'');
if($role==='student'){$q=$pdo->prepare('SELECT st.id FROM students st WHERE st.user_id=?');$q->execute([$_SESSION['user']['id']]);$studentId=(int)$q->fetchColumn();}
elseif($role!=='admin'){header('Location: dashboard.php');exit;}
$q=$pdo->prepare('SELECT st.*,u.name,u.email,p.level,p.name program_name,p.specialization FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id WHERE st.id=?');$q->execute([$studentId]);$student=$q->fetch();if(!$student)exit('Student not found.');
if($term==='')$term=$student['semester_or_year'];
$result=studentResult($pdo,$studentId,$term); $overall=studentOverall($pdo,$studentId);
$pageTitle='Result Card';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result Card - <?=htmlspecialchars($student['name'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#fff;font-family:Arial,sans-serif}.card-wrap{max-width:1050px;margin:25px auto}.logo-box{width:78px;height:78px;border:2px solid #173f68;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;color:#173f68;font-size:25px}.head{border-bottom:4px solid #ffd447}.meta td{padding:5px 12px}.result th{background:#173f68;color:#fff}.result td,.result th{border:1px solid #bfc7d1}.summary{border:1px solid #bfc7d1;padding:12px}.signature{height:80px;border-bottom:1px solid #777}.no-print{display:block}@media print{.no-print{display:none!important}.card-wrap{margin:0;max-width:none}body{font-size:12px}}</style></head><body><div class="card-wrap"><div class="no-print text-end mb-3"><button onclick="window.print()" class="btn btn-primary">Print / Save PDF</button><?php if($role==='admin'):?><a href="admin/results.php?student_id=<?=$studentId?>" class="btn btn-outline-secondary">Back</a><?php else:?><a href="student.php" class="btn btn-outline-secondary">Back</a><?php endif;?></div><div class="head pb-3 mb-3"><div class="d-flex align-items-center gap-3"><div class="logo-box">IMCB</div><div><h2 class="mb-1 fw-bold">ISLAMABAD MODEL COLLEGE FOR BOYS, F-10/4</h2><div class="text-muted">College & BS/ADP Academic Portal</div><h5 class="mt-2 mb-0">STUDENT RESULT CARD / DMC</h5></div></div></div><table class="meta w-100 mb-3"><tr><td><strong>Student Name:</strong> <?=htmlspecialchars($student['name'])?></td><td><strong>Roll No:</strong> <?=htmlspecialchars($student['roll_no'])?></td></tr><tr><td><strong>Program:</strong> <?=htmlspecialchars($student['program_name'])?><?php if($student['specialization']):?> — <?=htmlspecialchars($student['specialization'])?><?php endif;?></td><td><strong>Level:</strong> <?=htmlspecialchars($student['level'])?></td></tr><tr><td><strong>Term:</strong> <?=htmlspecialchars($term)?></td><td><strong>Email:</strong> <?=htmlspecialchars($student['email'])?></td></tr></table><div class="table-responsive"><table class="table result"><thead><tr><th>#</th><th>Code</th><th>Subject</th><th>Credit Hours</th><th>Obtained</th><th>Total</th><th>%</th><th>Grade</th><th>GP</th><th>Quality Points</th></tr></thead><tbody><?php foreach($result['rows'] as $i=>$r):?><tr><td><?=$i+1?></td><td><?=htmlspecialchars($r['code'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=number_format($r['credit_hours'],1)?></td><td><?=number_format($r['obtained'],2)?></td><td><?=number_format($r['total'],2)?></td><td><?=number_format($r['percent'],2)?>%</td><td><?=htmlspecialchars($r['letter_grade'])?></td><td><?=number_format($r['grade_point'],2)?></td><td><?=number_format($r['quality_points'],2)?></td></tr><?php endforeach;if(!$result['rows']):?><tr><td colspan="10" class="text-center">No result data available for this term.</td></tr><?php endif;?></tbody></table></div><div class="summary row g-2 mt-3"><div class="col-md-3"><strong>Term Credit Hours:</strong><br><?=number_format($result['credits'],1)?></div><div class="col-md-3"><strong>Term Quality Points:</strong><br><?=number_format($result['quality'],2)?></div><div class="col-md-3"><strong>Semester / Term GPA:</strong><br><?=number_format($result['gpa'],2)?></div><div class="col-md-3"><strong>Overall GPA:</strong><br><?=number_format($overall['gpa'],2)?></div></div><div class="row mt-5"><div class="col-4 text-center"><div class="signature"></div><small>Class Incharge</small></div><div class="col-4 text-center"><div class="signature"></div><small>Head of Department</small></div><div class="col-4 text-center"><div class="signature"></div><small>Principal</small></div></div><p class="small text-muted mt-4">This portal-generated result card is subject to verification and official institutional approval.</p></div></body></html>
